# diagonal line groups, both slopes. collect coordinate by invariant
for slope in (1,-1):
    groups={}
    for r in range(R):
        for c in range(C):
            if grid[r][c]==0:
                key=(c-r if slope==1 else c+r)
                groups.setdefault(key,[]).append((r,c))
    for pts in groups.values():
        pts.sort()
        for (r1,c1),(r2,c2) in zip(pts,pts[1:]):
            dr=(r2-r1)//abs(r2-r1) if r2!=r1 else 0
            dc=(c2-c1)//abs(c2-c1) if c2!=c1 else 0
            # only diagonal; groups guarantees diagonal alignment
            for k in range(1,r2-r1):
                rr=r1+k; cc=c1+k*dc
                if grid[rr][cc]==9: out2[rr][cc]=3
print('\n'.join(' '.join(map(str,row)) for row in out2))

